#!/usr/bin/env node
// Writes src/changelog-bundled.ts: the release notes the app ships with, so 设置 → 关于 → 更新日志 shows the running
// version's notes (and the whole history) even offline. Source = the `releaseBody` block of
// .github/workflows/release-desktop-auto-update.yml, the same text the release, latest.json and android/<ver>/notes.md use.
//
//   node scripts/changelog-bundle.mjs            # after editing releaseBody (the version bump PR); also refreshes the
//                                                # release dates from `gh api` when gh is available (kept otherwise)
//   node scripts/changelog-bundle.mjs --no-dates # skip the gh call
//
// src/changelog-bundled.test.ts fails when the bundled text drifts from the workflow, with this command as the fix.
// Dates already in the file are kept; a run only adds / updates them.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { extractReleaseBody } from './android-release-notes.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const WORKFLOW = join(root, '.github/workflows/release-desktop-auto-update.yml');
const OUT = join(root, 'src/changelog-bundled.ts');

/** The file's text for a body + dates (exported for the drift test). */
export function renderBundled(body, dates) {
  const lines = body.split('\n').map((l) => `  ${JSON.stringify(l)},`);
  const dateLines = Object.keys(dates)
    .sort((a, b) => b.localeCompare(a, 'en', { numeric: true }))
    .map((v) => `  ${JSON.stringify(v)}: ${JSON.stringify(dates[v])},`);
  return [
    '// GENERATED by scripts/changelog-bundle.mjs from the releaseBody of .github/workflows/release-desktop-auto-update.yml.',
    '// Do not edit by hand: change releaseBody, then run `node scripts/changelog-bundle.mjs` (the version bump PR does this).',
    '// 设置 → 关于 → 更新日志 shows these notes when the mirror / GitHub cannot be reached (src/changelog-source.ts).',
    '',
    'export const BUNDLED_RELEASE_BODY: string = [',
    ...lines,
    "].join('\\n');",
    '',
    '/** Release date (published_at) per version, as far as it was known when this file was generated. */',
    'export const BUNDLED_RELEASE_DATES: Record<string, string> = {',
    ...dateLines,
    '};',
    '',
  ].join('\n');
}

/** Dates already recorded in the current file (so a run without gh, or with --no-dates, keeps them). */
export function existingDates(text) {
  const out = {};
  // A Windows checkout (autocrlf) has CRLF; the generator always writes LF.
  const block = /BUNDLED_RELEASE_DATES[^{]*\{([\s\S]*?)\n\};/.exec(String(text ?? '').replace(/\r\n?/g, '\n'));
  if (!block) return out;
  for (const m of block[1].matchAll(/^\s*"([^"]+)":\s*"([^"]+)",?$/gm)) out[m[1]] = m[2];
  return out;
}

function githubDates() {
  const raw = execFileSync('gh', ['api', '--paginate', 'repos/sleep2agi/agent-network-app/releases?per_page=100', '--jq', '.[] | select(.draft == false and .prerelease == false) | [.tag_name, .published_at] | @tsv'], { encoding: 'utf8' });
  const out = {};
  for (const line of raw.split('\n')) {
    const [tag, at] = line.split('\t');
    const m = /^desktop-v(\d+\.\d+\.\d+)$/.exec(tag ?? '');
    if (m && at) out[m[1]] = at.trim();
  }
  return out;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const body = extractReleaseBody(readFileSync(WORKFLOW, 'utf8'));
  if (!body) {
    console.error('::error::no releaseBody block in the release workflow');
    process.exit(1);
  }
  const dates = existingDates(existsSync(OUT) ? readFileSync(OUT, 'utf8') : '');
  // Dates are refreshed on every run now (they had stopped at 0.2.165 because the bump PR ran this without --dates,
  // so the offline 更新日志 showed no date for 0.2.166–0.2.186). No gh / no auth / offline → keep the recorded ones.
  if (!process.argv.includes('--no-dates')) {
    try { Object.assign(dates, githubDates()); }
    catch (error) { console.warn(`note: release dates not refreshed (${String(error?.message ?? error).split('\n')[0]}); keeping ${Object.keys(dates).length} recorded`); }
  }
  writeFileSync(OUT, renderBundled(body, dates));
  console.log(`wrote ${OUT} (${body.split('\n').length} lines, ${Object.keys(dates).length} dates)`);
}
